```c++
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string wordToSearch; // palabra a buscar
    string line; // línea del archivo

    // obtener la palabra a buscar desde el usuario
    cout << "Introduzca la palabra a buscar: ";
    cin >> wordToSearch;

    // abrir el archivo para leer
    ifstream file("archivo.txt");

    // verificar si el archivo se abrió correctamente
    if (!file) {
        cout << "No se pudo abrir el archivo." << endl;
        return 1;
    }

    int count = 0; // contador de apariciones de la palabra

    // leer línea por línea del archivo
    while (getline(file, line)) {
        // buscar la palabra en la línea actual
        size_t pos = line.find(wordToSearch);
        while (pos != string::npos) {
            // si se encuentra la palabra, incrementar el contador
            count++;
            // buscar la siguiente aparición de la palabra
            pos = line.find(wordToSearch, pos + 1);
        }
    }

    // cerrar el archivo
    file.close();

    // mostrar el número de apariciones de la palabra
    cout << "El número de apariciones de \"" << wordToSearch << "\" en el archivo es: " << count << endl;

    return 0;
}
